package com.smartgrocery.entity; import jakarta.persistence.*; import java.math.BigDecimal; @Entity @Table(name="inventory") public class Inventory { @Id @GeneratedValue(strategy=GenerationType.IDENTITY) private Long id; @OneToOne(optional=false) @JoinColumn(name="product_id",unique=true) private Product product; @Column(nullable=false,precision=12,scale=3) private BigDecimal physicalStock=BigDecimal.ZERO; @Column(nullable=false,precision=12,scale=3) private BigDecimal reservedStock=BigDecimal.ZERO; private BigDecimal reorderLevel=BigDecimal.TEN; @Version private Long version; public Inventory(){} public Inventory(Product p,BigDecimal q){product=p;physicalStock=q;} public Long getId(){return id;} public Product getProduct(){return product;} public BigDecimal getPhysicalStock(){return physicalStock;} public BigDecimal getReservedStock(){return reservedStock;} public BigDecimal getAvailableStock(){return physicalStock.subtract(reservedStock);} public BigDecimal getReorderLevel(){return reorderLevel;} public void setPhysicalStock(BigDecimal v){physicalStock=v;} public void setReservedStock(BigDecimal v){reservedStock=v;} public void setReorderLevel(BigDecimal v){reorderLevel=v;} }